do $$ declare v_program bigint; begin select id into v_program from private.exam_prep_program_versions where program_key='math_as_p1_p5' and version_key='p1_p5_canonical_v1_0'; if not private.exam_prep_skill_content_ready_v1(v_program,'P5','P5-DRV-02') then raise exception 'DRV-02 not ready after publish'; end if; if exists(select 1 from public.questions where book_ref like 'ExamPrep:P5:p5_aw13_16_drv02_v1:%' and is_active) then raise exception 'legacy activation residue'; end if; if exists(select 1 from private.exam_prep_feature_config where program_key='math_as_p1_p5' and (rollout_state<>'off' or core_enabled or ai_enabled or mentor_enabled or not kill_switch)) then raise exception 'feature escaped fail-closed'; end if; if exists(select 1 from private.exam_prep_feature_entitlements where entitlement_status='active') then raise exception 'active entitlement residue'; end if; end $$;
